// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    function testFuzz_property(uint256 n, address from, address token, uint256 v) public {
        // Keep array length modest but wide; 0 is admissible for the mutant-only
        // distinction via the public return value.
        n = bound(n, 0, 16);

        RecordingToken rec = new RecordingToken();
        token = address(rec);

        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(i, from)))));
        }

        bool ok = true;
        try c.transfer(from, token, tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // General rule: on the reference, an empty recipient array must revert
        // (so `ok` is false for n == 0) and a non-empty array must succeed
        // (ok is true for n > 0). The mutant weakens the require to `require(true)`,
        // so it returns true for n == 0, breaking the rule. Simultaneously,
        // because the token helper always returns success, the reference must
        // perform exactly one transferFrom call per recipient.
        assertTrue((n == 0) ? (ok == false && rec.callCount() == 0) : (ok == true && rec.callCount() == n));
    }
}

// Minimal recording adversarial/observing counterparty: always reports success
// for transferFrom and records the number of calls it received.
contract RecordingToken {
    uint256 public callCount;

    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        return true;
    }
}
